package com.asmj.marketplace.masterdata;
import java.security.Principal;import java.time.Instant;import java.util.*;
import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller
public class MasterDataController {
 private final MasterDataOptionRepository repo; public MasterDataController(MasterDataOptionRepository r){repo=r;}
 @GetMapping("/admin/master-data") public String page(Model m){m.addAttribute("options",repo.findAllByOrderByGroupKeyAscSortOrderAscLabelAsc());m.addAttribute("option",new MasterDataOption());return "admin/master-data";}
 @GetMapping("/admin/master-data/{id}/edit") public String edit(@PathVariable String id,Model m){m.addAttribute("options",repo.findAllByOrderByGroupKeyAscSortOrderAscLabelAsc());m.addAttribute("option",repo.findById(id).orElseThrow());return "admin/master-data";}
 @GetMapping("/admin/master-data/{id}/edit") public String edit(@PathVariable String id,Model m){m.addAttribute("options",repo.findAllByOrderByGroupKeyAscSortOrderAscLabelAsc());m.addAttribute("option",repo.findById(id).orElseThrow());return "admin/master-data";}
 @PostMapping("/admin/master-data") public String save(@ModelAttribute MasterDataOption option,Principal p,RedirectAttributes ra){try{String group=clean(option.getGroupKey()).toUpperCase(Locale.ROOT);String code=clean(option.getCode()).toUpperCase(Locale.ROOT).replaceAll("[^A-Z0-9_-]","_");String label=clean(option.getLabel());if(group.length()>60||code.isBlank()||code.length()>80||label.length()>120)throw new IllegalArgumentException("Check the group, code and label lengths.");Optional<MasterDataOption> duplicate=repo.findByGroupKeyAndCode(group,code);if(duplicate.isPresent()&&!Objects.equals(duplicate.get().getId(),option.getId()))throw new IllegalArgumentException("This code already exists in that dropdown group.");option.setGroupKey(group);option.setCode(code);option.setLabel(label);option.setUpdatedAt(Instant.now());option.setUpdatedBy(p.getName());repo.save(option);ra.addFlashAttribute("successMessage","Dropdown option saved.");}catch(IllegalArgumentException e){ra.addFlashAttribute("errorMessage",e.getMessage());}return "redirect:/admin/master-data";}
 @PostMapping("/admin/master-data/{id}/toggle") public String toggle(@PathVariable String id,Principal p,RedirectAttributes ra){repo.findById(id).ifPresent(o->{o.setActive(!o.isActive());o.setUpdatedAt(Instant.now());o.setUpdatedBy(p.getName());repo.save(o);});ra.addFlashAttribute("successMessage","Dropdown option status updated. Existing saved values are preserved.");return "redirect:/admin/master-data";}
 @GetMapping("/api/master-data/{group}") @ResponseBody public List<Map<String,Object>> options(@PathVariable String group,@RequestParam(required=false) String parent){return repo.findByGroupKeyAndActiveTrueOrderBySortOrderAscLabelAsc(group.toUpperCase(Locale.ROOT)).stream().filter(o->parent==null||parent.isBlank()||Objects.equals(parent,o.getParentCode())).map(o->{Map<String,Object> m=new LinkedHashMap<>();m.put("code",o.getCode());m.put("label",o.getLabel());m.put("parentCode",o.getParentCode());return m;}).toList();}
 private String clean(String s){return s==null?"":s.trim();}
}
